R=Path(__file__).resolve().parents[2];D=R/'development/vertical-city-v02';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();read=lambda p:json.loads(p.read_text());prior=read(D/'V02_Facade_Architecture_Evidence.json');source=R/prior['entry'];assert sha(source)==prior['entrySHA256'];text=source.read_text();old="(state.pilot?'pilot':'coffered/runtime')";new="(state.pilot?'pilot':'gallery-arcades/runtime')";assert text.count(old)==1;entry=R/'SIGHTLINE_SAINT_MERIDIAN_V02_GALLERY_ARCADES.html';entry.write_text(text.replace(old,new,1));assert entry.read_text().replace(new,old,1)==text
report={'status':'CANDIDATE; native/source/input/visual acceptance pending','entry':entry.name,'entrySHA256':sha(entry),'source':source.name,'sourceSHA256':sha(source),'oldSelector':old,'newSelector':new,'manifest':'assets/city/vertical-v02/gallery-arcades/runtime/manifest.json','manifestSHA256':sha(R/'assets/city/vertical-v02/gallery-arcades/runtime/manifest.json'),'scope':'Only V02 geometry-manifest folder changes. All existing gameplay/shader/camera/input/hero/resource systems remain unchanged.'};(D/'V02_Gallery_Arcade_Build.json').write_text(json.dumps(report,indent=2)+'\n');print(entry.name,report['entrySHA256'])
